WITH AnchorYears AS (SELECT DATAAREAID, YEAR(MAX(InvoiceDate)) AS AnchorYear FROM VendInvoiceJour GROUP BY DATAAREAID), InvoicedMetrics AS (SELECT vij.DATAAREAID, vij.InvoiceAccount, SUM(vij.InvoiceAmount) AS InvoicedAmount FROM VendInvoiceJour vij JOIN AnchorYears ay ON vij.DATAAREAID = ay.DATAAREAID AND YEAR(vij.InvoiceDate) = ay.AnchorYear GROUP BY vij.DATAAREAID, vij.InvoiceAccount), POMetrics AS (SELECT pt.DATAAREAID, pt.OrderAccount, SUM(pl.LineAmount) AS TotalPOAmount FROM PurchTable pt JOIN PurchLine pl ON pt.PurchId = pl.PurchId AND pt.DATAAREAID = pl.DATAAREAID JOIN AnchorYears ay ON pt.DATAAREAID = ay.DATAAREAID AND YEAR(pt.AccountingDate) = ay.AnchorYear GROUP BY pt.DATAAREAID, pt.OrderAccount), ReceiptMetrics AS (SELECT vpsj.DATAAREAID, vpsj.PurchId, SUM(vpst.ValueMST) AS TotalReceiptAmount FROM VendPackingSlipJour vpsj JOIN VendPackingSlipTrans vpst ON vpsj.PackingSlipId = vpst.PackingSlipId AND vpsj.DATAAREAID = vpst.DATAAREAID JOIN AnchorYears ay ON vpsj.DATAAREAID = ay.DATAAREAID AND YEAR(vpsj.DocumentDate) = ay.AnchorYear GROUP BY vpsj.DATAAREAID, vpsj.PurchId), PaymentMetrics AS (SELECT vt.DATAAREAID, vt.AccountNum, SUM(vt.AmountCur) AS TotalPayments FROM VendTrans vt JOIN AnchorYears ay ON vt.DATAAREAID = ay.DATAAREAID AND YEAR(vt.TransDate) = ay.AnchorYear GROUP BY vt.DATAAREAID, vt.AccountNum) SELECT TOP 10 v.AccountNum, d.Name, ISNULL(po.TotalPOAmount, 0) AS TotalPOAmount, ISNULL(rm.TotalReceiptAmount, 0) AS ReceiptAmount, inv.InvoicedAmount, ISNULL(pm.TotalPayments, 0) AS Payments, NULL AS PRAmount FROM VendTable v JOIN DirPartyTable d ON v.Party = d.RecId JOIN InvoicedMetrics inv ON v.AccountNum = inv.InvoiceAccount AND v.DATAAREAID = inv.DATAAREAID LEFT JOIN POMetrics po ON v.AccountNum = po.OrderAccount AND v.DATAAREAID = po.DATAAREAID LEFT JOIN (SELECT pt.OrderAccount, pt.DATAAREAID, SUM(r.TotalReceiptAmount) AS TotalReceiptAmount FROM PurchTable pt JOIN ReceiptMetrics r ON pt.PurchId = r.PurchId AND pt.DATAAREAID = r.DATAAREAID GROUP BY pt.OrderAccount, pt.DATAAREAID) rm ON v.AccountNum = rm.OrderAccount AND v.DATAAREAID = rm.DATAAREAID LEFT JOIN PaymentMetrics pm ON v.AccountNum = pm.AccountNum AND v.DATAAREAID = pm.DATAAREAID ORDER BY inv.InvoicedAmount DESC
